// ТЕСТ кадра Рыжа (этап 1 рилса #1). Воркфлоу временный — удалить после подгонки.
// Только картинка: эталон-спрайт → nano-banana edit → кадр 9:16 в Телеграм. ~$0.04 за картинку.
// Крутим тут: FRAMES (сцены), NUM (вариантов на сцену), MODEL.

// 'fal-ai/nano-banana/edit' (~$0.04) или 'fal-ai/nano-banana-pro/edit' (дороже, обычно точнее держит персонажа).
const MODEL = 'fal-ai/nano-banana/edit';
const NUM = 2;

// Эталоны = реальные спрайты приложения (GitHub Pages фронта). m — мышцы 0..3, b — живот 0..3.
const REF = (m, b, hungry) => `https://perevyazko1.github.io/n8n-fitness-scan/img/fox_m${m}_b${b}${hungry ? '_hungry' : ''}.png`;

// Что НЕЛЬЗЯ менять в персонаже — Veo/модели любят «дорисовать» настоящую лису или Pixar.
const KEEP = [
  "Keep the fox character IDENTICAL to the reference image: same 2D flat vector cartoon style, same thick clean black outlines, same soft cel shading, same colors, same proportions, same face.",
  "Orange fur #E8763A, cream #F7E4CF muzzle/chest/belly, orange paws with cream toes (NO black paws, NO dark gloves), ears orange with cream insides (NO black ear tips),",
  "orange headband clearly separate from the head fur, orange wristbands on both wrists, black shorts with an orange side stripe.",
  "BAREFOOT: bare cream fox paws on the feet, NO shoes, NO sneakers, NO socks.",
  "Ears: orange with a thin orange-brown outline and cream insides, NO black or dark ear tips.",
  "Headband: NARROW orange band sitting HIGH on the forehead, well above the eyebrows, with the orange hair tuft sticking up above it.",
  "Eyebrows: short thin dark-brown brows, not thick black ones.",
  "Fur edges: smooth clean outlines like the reference, NOT jagged, spiky or sketchy fur tufts on cheeks and arms.",
  "Shorts: plain black shorts with ONE vertical orange stripe on the side only, NO colored trim on the hem, NO double stripes.",
  "Do NOT make it 3D, Pixar-like, realistic or furry-detailed. Only change the pose, facial expression and background.",
].join(' ');

const STYLE_BG = "The background must be drawn in the same flat 2D vector cartoon style with bold outlines and simple shapes, so the character and the scene look like one illustration. Vertical 9:16 composition. No text, no letters, no logos.";

// on: false — сцену пропустить (чтобы не платить за то, что уже устроило).
const FRAMES = [
  {
    key: 'hook',
    on: false, // утверждён 23.09 — не перегенерим
    ref: REF(2, 2),
    scene: "Night kitchen, open glowing fridge on the left. The fox stands in front of the fridge holding a half-eaten sandwich in one paw, looking down at his own round belly in shock: eyes wide, ears up, mouth open. Visible from the knees up, character takes most of the frame, head in the upper third. Warm dim light plus cool blue glow from the fridge.",
  },
  {
    key: 'cta',
    on: false, // утверждён 23.09 (вариант 4) — не перегенерим
    ref: REF(3, 0),
    scene: "Bright cozy home gym corner, soft daylight. The fox stands confidently facing the viewer, pointing one paw at the camera, giving a sly wink and a cheeky smile. Visible from the knees up, character centered and large in the frame, head in the upper third. The illustration fills the whole frame edge to edge, no borders.",
  },
  {
    // Сцена 2 «знакомство»: мостик к записи телефона — Рыж выпрыгивает из экрана.
    key: 'intro',
    on: false, // утверждён intro 2 (прогон 23.09 16:20)
    ref: REF(2, 1),
    scene: "A big modern smartphone standing upright on a wooden desk in a cozy bright room. The fox is leaping OUT of the glowing phone screen toward the viewer: his upper body and one waving paw are already outside the screen, legs still inside the screen glow. Big friendly smile, excited eyes. The phone screen shows only a soft blue glow, no interface, no icons. Character large in the frame, head in the upper third.",
  },
  {
    // Сцена 5 «результат», СТАРТОВЫЙ кадр: пузатый Рыж в приседе — Veo доиграет до подтянутого.
    key: 'result_start',
    on: false, // утверждён вариант 1 (пузо, присед, капля пота)
    ref: REF(2, 2),
    scene: "Bright cozy home gym corner with a yoga mat, a dumbbell rack and a window with daylight. The fox with a round belly is doing a bodyweight squat on the mat, arms stretched forward, determined face, a drop of sweat on his forehead. Visible from the knees up, character centered and large, head in the upper third.",
  },
  {
    // Сцена 5, ФИНАЛЬНЫЙ кадр — ПРАВКОЙ утверждённого стартового: та же комната/коврик/свет,
    // меняется только тело Рыжа. Нужен для режима «первый + последний кадр» у Veo:
    // если фон разный, Veo превращает всю комнату, а не лиса.
    key: 'result_end',
    on: true,
    ref: [
      "https://v3b.fal.media/files/b/0aab9956/3lxFh3yVX2pAQLT3vNan0_jqbcTXFc.png", // стартовый кадр — сцена
      REF(3, 0),                                                                   // эталон тела
    ],
    scene: "Edit the FIRST image. Keep the room, the purple yoga mat, the dumbbell rack, the window, the lighting, the camera angle and framing EXACTLY the same. Change only the fox: he is now fit with a flat toned stomach and defined abs like the fox in the SECOND image, standing upright on the same spot of the mat and proudly flexing one bicep with a big confident grin. No sweat drop.",
  },
];

const out = [];
for (const f of FRAMES) {
  if (!f.on) continue;
  out.push({ json: {
    key: f.key,
    model: MODEL,
    ref_urls: Array.isArray(f.ref) ? f.ref : [f.ref],
    num: NUM,
    // Правка кадра (ref-массив): тело меняем намеренно и фон держим — фразы KEEP
    // про «те же пропорции / меняй только фон» тут противоречили бы задаче.
    prompt: (Array.isArray(f.ref)
      ? [f.scene, KEEP.replace('same proportions, ', '').replace(' Only change the pose, facial expression and background.', ''), 'Same flat 2D cartoon style as both images. No text, no letters, no logos.']
      : ['Use the character from the reference image.', f.scene, KEEP, STYLE_BG]).join('\n'),
  } });
}
return out;

// Каждая картинка ответа fal → отдельный item для отправки в Телеграм.
const out = [];
$input.all().forEach((it, i) => {
  const src = $('Кадры').all()[i].json;
  (it.json.images || []).forEach((img, j) => {
    out.push({ json: { url: img.url, caption: `${src.key} · вариант ${j + 1} · ${src.model.split('/')[1]}` } });
  });
});
return out;
